class Solution {
public:
    string lexSmallestAfterDeletion(string s) {
        int freq[26] = {0};

        for (char c : s) {
            freq[c - 'a']++;
        }

        string st;

        for (char c : s) {
            while (!st.empty() &&
                   st.back() > c &&
                   freq[st.back() - 'a'] > 1) {

                freq[st.back() - 'a']--;
                st.pop_back();
            }

            st.push_back(c);
        }

        // Remove unnecessary duplicates at the end.
        while (!st.empty() &&
               freq[st.back() - 'a'] > 1) {

            freq[st.back() - 'a']--;
            st.pop_back();
        }

        return st;
    }
};
